text(await tools.exec_command({cmd:"@'
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const hash = p => createHash('sha256').update(readFileSync(p)).digest('hex');
const baseline = JSON.parse(readFileSync('.agent/remaining-qualification/source-snapshot.json'));
const changes = Object.entries(baseline.production).filter(([p,h]) => hash(p)!==h).map(([p])=>p);
assert.deepEqual(changes,['app/ui/assets/scoped-client.js']);
assert.equal(hash('docs/adr/0011-named-knowledge-spaces-dashboard.md'),baseline.retained['docs/adr/0011-named-knowledge-spaces-dashboard.md']);
const scope=JSON.parse(readFileSync('.agent/401-repair/scope.json'));
for(const [p,h] of Object.entries(scope.files)) assert.equal(hash(p),h,p);
